import { Link, useSearchParams } from "react-router-dom";
import { useMemo } from "react";
import {
  posts,
  getAllTags,
  getAllCategories,
  getArchiveMonths,
  groupByMonth,
} from "content/posts";
import { formatDate } from "content/markdown";

const ReadMoreIcon = () => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="18"
    height="18"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="M7 7h10v10"></path>
    <path d="M7 17 17 7"></path>
  </svg>
);

const tagBase =
  "inline-block border rounded-full px-3 py-1 text-xs cursor-pointer transition-colors no-underline";

const BlogsScreen = () => {
  const [params, setParams] = useSearchParams();
  const tag = params.get("tag") || "";
  const month = params.get("month") || "";
  const category = params.get("category") || "";
  const q = (params.get("q") || "").toLowerCase();

  const tags = useMemo(() => getAllTags(), []);
  const categories = useMemo(() => getAllCategories(), []);
  const months = useMemo(() => getArchiveMonths(), []);

  const filtered = useMemo(() => {
    return posts.filter((p) => {
      if (tag && !p.tags.includes(tag)) return false;
      if (category && p.category !== category) return false;
      if (month && !p.date.startsWith(month)) return false;
      if (q) {
        const hay = (
          p.title +
          " " +
          p.excerpt +
          " " +
          p.tags.join(" ")
        ).toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
  }, [tag, category, month, q]);

  const grouped = useMemo(() => groupByMonth(filtered), [filtered]);
  const hasFilters = tag || month || category || q;

  const setParam = (key, value) => {
    const next = new URLSearchParams(params);
    if (value && next.get(key) !== value) next.set(key, value);
    else next.delete(key);
    setParams(next);
  };
  const clearAll = () => setParams(new URLSearchParams());

  return (
    <div className="pt-16 pb-14">
      {/* Header */}
      <div className="text-center flex flex-col gap-3 mt-6">
        <h1 className="text-3xl md:text-4xl font-semibold">Blog</h1>
        <p className="text-gray-500">
          Notes on blockchain development, RWA, DeFi and white-label delivery.
        </p>
      </div>

      <div className="max-w-6xl mx-auto px-4 mt-10 grid grid-cols-1 lg:grid-cols-3 gap-10">
        {/* ---- Main list ---- */}
        <div className="lg:col-span-2">
          <div className="mb-6">
            <input
              type="search"
              className="w-full px-4 py-3 border border-gray-200 rounded-lg text-[15px] outline-none focus:border-brand"
              placeholder="Search posts…"
              defaultValue={params.get("q") || ""}
              onChange={(e) => setParam("q", e.target.value)}
              aria-label="Search posts"
            />
            {hasFilters ? (
              <div className="flex flex-wrap gap-2 items-center mt-3">
                {tag && (
                  <button
                    className="bg-black text-white border-0 rounded-full px-3 py-1 text-[13px] cursor-pointer"
                    onClick={() => setParam("tag", "")}
                  >
                    #{tag} ✕
                  </button>
                )}
                {category && (
                  <button
                    className="bg-black text-white border-0 rounded-full px-3 py-1 text-[13px] cursor-pointer"
                    onClick={() => setParam("category", "")}
                  >
                    {category} ✕
                  </button>
                )}
                {month && (
                  <button
                    className="bg-black text-white border-0 rounded-full px-3 py-1 text-[13px] cursor-pointer"
                    onClick={() => setParam("month", "")}
                  >
                    {months.find((m) => m.key === month)?.label || month} ✕
                  </button>
                )}
                <button
                  className="bg-transparent border-0 text-gray-400 text-[13px] underline cursor-pointer"
                  onClick={clearAll}
                >
                  Clear all
                </button>
              </div>
            ) : null}
          </div>

          {grouped.length === 0 && (
            <p className="py-10 text-center text-gray-500">
              No posts match these filters yet.
            </p>
          )}

          {grouped.map((g) => (
            <div key={g.key}>
              <h2 className="text-sm font-bold uppercase tracking-wider text-neutral-900 pb-2 mt-9 mb-6 border-b-2 border-brand">
                {g.label}
              </h2>
              {g.posts.map((p) => (
                <article
                  key={p.slug}
                  className="flex flex-col sm:flex-row gap-5 mb-9"
                >
                  <Link
                    to={`/blogs/${p.slug}`}
                    className="shrink-0 w-full sm:w-60 h-44 overflow-hidden rounded-xl bg-[#15161c] flex items-center justify-center"
                  >
                    <img
                      src={p.image}
                      alt={p.title}
                      className="w-full h-full object-contain hover:scale-105 transition-transform duration-300"
                    />
                  </Link>
                  <div className="flex-1">
                    <div className="flex gap-4 items-center text-sm">
                      <button
                        className="bg-transparent border-0 p-0 underline text-neutral-900 cursor-pointer"
                        onClick={() => setParam("category", p.category)}
                      >
                        {p.category}
                      </button>
                      <span className="font-light text-gray-500">
                        {formatDate(p.date)} · {p.minutes} min read
                      </span>
                    </div>
                    <h3 className="text-xl font-semibold mt-2">
                      <Link
                        className="text-neutral-900 no-underline hover:text-brand-ink"
                        to={`/blogs/${p.slug}`}
                      >
                        {p.title}
                      </Link>
                    </h3>
                    <p className="text-gray-500 mt-2">{p.excerpt}</p>
                    <div className="flex flex-wrap gap-2 my-3">
                      {p.tags.map((t) => (
                        <button
                          key={t}
                          className={`${tagBase} bg-gray-100 border-gray-200 text-gray-600 hover:bg-brand hover:border-brand hover:text-neutral-900`}
                          onClick={() => setParam("tag", t)}
                        >
                          #{t}
                        </button>
                      ))}
                    </div>
                    <Link
                      className="inline-flex items-center gap-1.5 no-underline font-normal text-neutral-900 hover:text-brand-ink"
                      to={`/blogs/${p.slug}`}
                    >
                      Read More <ReadMoreIcon />
                    </Link>
                  </div>
                </article>
              ))}
            </div>
          ))}
        </div>

        {/* ---- Sidebar ---- */}
        <aside className="lg:col-span-1">
          <Widget title="Archive">
            <ul className="list-none p-0 m-0">
              {months.map((m) => (
                <ArchiveItem
                  key={m.key}
                  active={month === m.key}
                  label={m.label}
                  count={m.count}
                  onClick={() => setParam("month", m.key)}
                />
              ))}
            </ul>
          </Widget>

          <Widget title="Categories">
            <ul className="list-none p-0 m-0">
              {categories.map((c) => (
                <ArchiveItem
                  key={c.category}
                  active={category === c.category}
                  label={c.category}
                  count={c.count}
                  onClick={() => setParam("category", c.category)}
                />
              ))}
            </ul>
          </Widget>

          <Widget title="Tags">
            <div className="flex flex-wrap gap-2">
              {tags.map((t) => (
                <button
                  key={t.tag}
                  className={`${tagBase} ${
                    tag === t.tag
                      ? "bg-brand border-brand text-neutral-900"
                      : "bg-gray-100 border-gray-200 text-gray-600 hover:bg-brand hover:border-brand hover:text-neutral-900"
                  }`}
                  onClick={() => setParam("tag", t.tag)}
                >
                  #{t.tag}
                </button>
              ))}
            </div>
          </Widget>
        </aside>
      </div>
    </div>
  );
};

const Widget = ({ title, children }) => (
  <div className="mb-9">
    <h4 className="text-base font-bold mb-3.5 pb-2 border-b border-gray-200">
      {title}
    </h4>
    {children}
  </div>
);

const ArchiveItem = ({ active, label, count, onClick }) => (
  <li>
    <button
      onClick={onClick}
      className={`w-full flex justify-between items-center bg-transparent border-0 py-2 cursor-pointer border-b border-dashed border-gray-200 ${
        active ? "text-neutral-900 font-semibold" : "text-gray-600"
      } hover:text-neutral-900`}
    >
      <span>{label}</span>
      <span className="bg-gray-100 rounded-full px-2.5 py-0.5 text-xs text-gray-500">
        {count}
      </span>
    </button>
  </li>
);

export default BlogsScreen;
