// Blog content layer.
// Each post is one file in ./items/*.js exporting a default object:
//   { slug, title, date: "YYYY-MM-DD", category, tags: [], excerpt, image, body }
// Drop a new file in ./items and it appears automatically — no edits needed here.

import { slugify, readingTime } from "../markdown";

// Auto-discover every post file in ./items
const ctx = require.context("./items", false, /\.js$/);

const loaded = ctx
  .keys()
  .filter((k) => !k.startsWith("./_")) // ignore _template.js etc.
  .map((k) => ctx(k).default)
  .filter(Boolean)
  .map((p) => ({
    ...p,
    slug: p.slug || slugify(p.title),
    tags: p.tags || [],
    minutes: readingTime(p.body),
  }));

// De-duplicate by slug — require.context can occasionally return a module more
// than once; keep the first occurrence so a post never renders twice.
const bySlug = new Map();
loaded.forEach((p) => {
  if (!bySlug.has(p.slug)) bySlug.set(p.slug, p);
});

export const posts = Array.from(bySlug.values())
  // newest first
  .sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0));

export const getPostBySlug = (slug) => posts.find((p) => p.slug === slug);

// [{ tag, count }] sorted by frequency
export const getAllTags = () => {
  const counts = {};
  posts.forEach((p) => p.tags.forEach((t) => (counts[t] = (counts[t] || 0) + 1)));
  return Object.entries(counts)
    .map(([tag, count]) => ({ tag, count }))
    .sort((a, b) => b.count - a.count || a.tag.localeCompare(b.tag));
};

// [{ category, count }]
export const getAllCategories = () => {
  const counts = {};
  posts.forEach((p) => {
    if (p.category) counts[p.category] = (counts[p.category] || 0) + 1;
  });
  return Object.entries(counts)
    .map(([category, count]) => ({ category, count }))
    .sort((a, b) => b.count - a.count || a.category.localeCompare(b.category));
};

const monthKey = (iso) => (iso || "").slice(0, 7); // "2026-07"
const monthLabel = (key) => {
  const [y, m] = key.split("-");
  const d = new Date(Number(y), Number(m) - 1, 1);
  return d.toLocaleDateString("en-US", { month: "long", year: "numeric" });
};

// [{ key: "2026-07", label: "July 2026", count }] newest first
export const getArchiveMonths = () => {
  const counts = {};
  posts.forEach((p) => {
    const k = monthKey(p.date);
    counts[k] = (counts[k] || 0) + 1;
  });
  return Object.entries(counts)
    .map(([key, count]) => ({ key, label: monthLabel(key), count }))
    .sort((a, b) => (a.key < b.key ? 1 : -1));
};

// Group a list of posts into [{ key, label, posts: [] }] newest month first
export const groupByMonth = (list) => {
  const groups = {};
  list.forEach((p) => {
    const k = monthKey(p.date);
    (groups[k] = groups[k] || []).push(p);
  });
  return Object.keys(groups)
    .sort((a, b) => (a < b ? 1 : -1))
    .map((key) => ({ key, label: monthLabel(key), posts: groups[key] }));
};
