import React, { Fragment, useState, useEffect } from "react";
import { Link, useNavigate, useLocation } from "react-router-dom";

const links = [
  { label: "Home", id: "home" },
  { label: "Blogs", to: "/blogs" },
  { label: "About Me", id: "about" },
  { label: "What I Do", id: "services" },
  { label: "Resume", id: "resume" },
  { label: "Portfolio", id: "portfolio" },
  { label: "FAQ", id: "faq" },
  { label: "Contact Me", id: "contact" },
];

const socials = [
  { label: "X (Twitter)", href: "https://twitter.com/PravinDev10", icon: "fab fa-twitter" },
  { label: "WhatsApp", href: "https://wa.me/919789741475", icon: "fab fa-whatsapp" },
  { label: "GitHub", href: "https://github.com/pravindev12", icon: "fab fa-github" },
  { label: "LinkedIn", href: "https://www.linkedin.com/in/pravin-raj-dev/", icon: "fab fa-linkedin-in" },
  { label: "Email", href: "mailto:pravinpersonal3@gmail.com", icon: "fas fa-envelope" },
];

const Header = () => {
  const [sticky, setSticky] = useState(false);
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    const onScroll = () => setSticky(window.pageYOffset > window.innerHeight * 0.3);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);

  const scrollToId = (id) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth" });
  };

  // On the home page → scroll to the section. On any other route → go home first, then scroll.
  const goToSection = (e, id) => {
    e.preventDefault();
    setOpen(false);
    if (location.pathname !== "/") {
      navigate("/");
      // wait for Home to mount before scrolling
      let tries = 0;
      const tick = () => {
        const el = document.getElementById(id);
        if (el) el.scrollIntoView({ behavior: "smooth" });
        else if (tries++ < 20) setTimeout(tick, 50);
      };
      setTimeout(tick, 60);
    } else {
      scrollToId(id);
    }
  };

  return (
    <Fragment>
      <header
        id="header"
        className={`sticky top-0 z-50 transition-colors duration-300 ${
          sticky ? "bg-white shadow-md" : "bg-transparent"
        }`}
      >
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <Link to="/" className="no-underline font-bold text-lg text-neutral-900">
            PRAVIN<span className="text-brand-ink">-DEV</span>
          </Link>

          <div className="flex items-center gap-4">
            <a
              href="tel:+919789741475"
              className="hidden md:inline-flex items-center gap-2 text-neutral-900 no-underline font-medium"
            >
              <i className="fas fa-phone"></i>
              (+91) 978 974 1475
            </a>
            <button
              type="button"
              onClick={() => setOpen(true)}
              aria-label="Open menu"
              className="w-10 h-10 flex items-center justify-center bg-transparent border-0 cursor-pointer text-neutral-900 text-xl"
            >
              <i className="fas fa-bars"></i>
            </button>
          </div>
        </div>
      </header>

      {/* Full-screen overlay menu */}
      <div
        className={`fixed inset-0 z-[60] bg-[#15161c] text-white transition-opacity duration-300 ${
          open ? "opacity-100 visible" : "opacity-0 invisible"
        }`}
      >
        <button
          type="button"
          onClick={() => setOpen(false)}
          aria-label="Close menu"
          className="absolute top-6 right-6 w-10 h-10 flex items-center justify-center bg-transparent border-0 cursor-pointer text-white text-2xl hover:text-brand"
        >
          <i className="fas fa-times"></i>
        </button>

        <div className="h-full flex flex-col items-center justify-center gap-8 px-6">
          <nav className="flex flex-col items-center gap-4 text-2xl font-semibold">
            {links.map((l) =>
              l.to ? (
                <Link
                  key={l.label}
                  to={l.to}
                  onClick={() => setOpen(false)}
                  className="no-underline text-white hover:text-brand transition-colors"
                >
                  {l.label}
                </Link>
              ) : (
                <a
                  key={l.label}
                  href={`#${l.id}`}
                  onClick={(e) => goToSection(e, l.id)}
                  className="no-underline text-white hover:text-brand transition-colors"
                >
                  {l.label}
                </a>
              )
            )}
          </nav>

          <div className="flex items-center gap-3 mt-4">
            {socials.map((s) => (
              <a
                key={s.label}
                href={s.href}
                target="_blank"
                rel="noreferrer"
                aria-label={s.label}
                title={s.label}
                className="w-10 h-10 rounded-full bg-white/10 text-white flex items-center justify-center no-underline hover:bg-brand hover:text-neutral-900 transition-colors"
              >
                <i className={s.icon}></i>
              </a>
            ))}
          </div>
        </div>
      </div>
    </Fragment>
  );
};

export default Header;
