import React, { Fragment, useState } from "react";
import carbonCore from "../../assets/images/projects/carboncore.jpg";
import krypcore from "../../assets/images/projects/krypcore.png";
import upexcise from "../../assets/images/projects/upexcise.png";
import hims from "../../assets/images/projects/hims.png";
import instantbitex from "../../assets/images/projects/instantbitex.png";
import tfm from "../../assets/images/projects/tfm.png";
import carbonMarket from "../../assets/images/projects/carbon-credit.svg";
import pharmaChain from "../../assets/images/projects/pharmachain.svg";

// Repos not yet public — cards point to the GitHub profile for now.
// TODO: swap to exact public repo / live-demo URLs once published.
const GH = "https://github.com/pravindev12";

const projects = [
  { name: "Carbon Credit Marketplace", category: "Web3", tag: "Web3 · RWA", image: carbonMarket, link: GH, bg: "#15161c", fit: "cover" },
  { name: "PharmaChain", category: "Web3", tag: "Web3 · RWA", image: pharmaChain, link: GH, bg: "#15161c", fit: "cover" },
  { name: "CarbonCore", category: "Web3", tag: "Web3", image: carbonCore, link: "#", bg: "#fff8dc", fit: "contain" },
  { name: "Krypcore", category: "Web3", tag: "Web3", image: krypcore, link: "#", bg: "#f5df4e", fit: "contain" },
  { name: "Instantbitex", category: "Web3", tag: "Web3", image: instantbitex, link: "#", bg: "#4169e1", fit: "contain" },
  { name: "UpExcise", category: "Web2", tag: "Web2", image: upexcise, link: "#", bg: "#ffffff", fit: "contain" },
  { name: "HMIS", category: "Web2", tag: "Web2", image: hims, link: "#", bg: "#f9ed25", fit: "contain" },
  { name: "TrueFriend Matrimony", category: "Web2", tag: "Web2", image: tfm, link: "#", bg: "#c084fc", fit: "contain" },
];

const TABS = ["All", "Web3", "Web2"];

const Card = ({ p }) => {
  const overlay = (
    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col items-center justify-center text-center px-3">
      <h5 className="text-white text-[21px] font-semibold">{p.name}</h5>
      <span className="text-neutral-200 mt-1">{p.tag}</span>
    </div>
  );
  const img = (
    <img
      src={p.image}
      alt={p.name}
      className={`w-full h-full ${p.fit === "cover" ? "object-cover" : "object-contain p-8"}`}
    />
  );
  const base =
    "group relative block rounded-xl overflow-hidden aspect-[4/3] no-underline";

  return p.link && p.link !== "#" ? (
    <a href={p.link} target="_blank" rel="noreferrer" aria-label={`View ${p.name}`} className={base} style={{ backgroundColor: p.bg }}>
      {img}
      {overlay}
    </a>
  ) : (
    <div className={base} style={{ backgroundColor: p.bg }}>
      {img}
      {overlay}
    </div>
  );
};

const Portfolio = () => {
  const [tab, setTab] = useState("All");
  const shown = tab === "All" ? projects : projects.filter((p) => p.category === tab);

  return (
    <Fragment>
      <section id="portfolio" className="relative overflow-hidden py-14 bg-[#f8f9fa]">
        <div className="max-w-6xl mx-auto px-4">
          <p className="text-center mb-2 wow fadeInUp" style={{ visibility: "visible" }}>
            <span className="bg-brand text-neutral-900 px-2">Portfolio</span>
          </p>
          <h2 className="text-[40px] leading-tight font-semibold text-center mb-8 wow fadeInUp" style={{ visibility: "visible" }}>
            Some of my most recent projects
          </h2>

          <div className="flex justify-center gap-2 mb-8">
            {TABS.map((t) => (
              <button
                key={t}
                onClick={() => setTab(t)}
                className={`px-5 py-2 font-bold bg-transparent border-0 border-b-2 cursor-pointer transition-colors ${
                  tab === t
                    ? "text-neutral-900 border-brand"
                    : "text-neutral-400 border-transparent hover:text-neutral-700"
                }`}
              >
                {t}
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {shown.map((p) => (
              <Card key={p.name} p={p} />
            ))}
          </div>
        </div>
      </section>
    </Fragment>
  );
};

export default Portfolio;
