import React from "react";
import ReactDOM from "react-dom/client";
import "./css/tailwind.css";
import "./css/index.css";
import App from "./App";

// Prerendered routes (scripts/prerender.js) ship #root pre-populated so
// crawlers get real content on the first HTTP response. Plain render (not
// hydrateRoot) is intentional: several components here mutate the DOM
// imperatively outside React (typed.js, WOW.js, owl-carousel), which makes
// clean hydration unreliable. A plain client render simply replaces the
// prerendered markup on mount — identical to the app's pre-existing
// behavior for real visitors, no regression.
const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
