import { Fragment, useMemo } from "react";
import { Link, useParams } from "react-router-dom";
import Seo from "common/seo";
import { getPostBySlug, posts } from "content/posts";
import { renderMarkdown, extractToc, formatDate } from "content/markdown";

const BlogDetail = () => {
  const { slug } = useParams();
  const post = getPostBySlug(slug);

  const html = useMemo(() => (post ? renderMarkdown(post.body) : ""), [post]);
  const toc = useMemo(() => (post ? extractToc(post.body) : []), [post]);

  const jumpTo = (id) => {
    const el = document.getElementById(id);
    if (el) {
      const top = el.getBoundingClientRect().top + window.scrollY - 90;
      window.scrollTo({ top, behavior: "smooth" });
    }
  };

  if (!post) {
    return (
      <div className="pt-16 pb-14">
        <div className="max-w-3xl mx-auto px-4 text-center py-10">
          <h1 className="text-3xl font-semibold mb-3">Post not found</h1>
          <p className="text-gray-500 mb-5">
            This post doesn’t exist or may have been moved.
          </p>
          <Link
            className="inline-block bg-black text-white px-5 py-2.5 no-underline"
            to="/blogs"
          >
            ← Back to all posts
          </Link>
        </div>
      </div>
    );
  }

  const idx = posts.findIndex((p) => p.slug === post.slug);
  const prev = posts[idx + 1]; // older
  const next = posts[idx - 1]; // newer

  const tagCls =
    "inline-block bg-gray-100 border border-gray-200 rounded-full px-3 py-1 text-xs text-gray-600 no-underline hover:bg-brand hover:border-brand hover:text-neutral-900 transition-colors";

  return (
    <Fragment>
      <Seo
        title={`${post.title} — Pravin Raj`}
        metaTitle={post.title}
        description={post.excerpt}
        image={post.image}
      />
      <div className="pt-16 pb-14">
        <div className="max-w-3xl mx-auto px-4">
          <Link
            className="inline-block mb-2.5 text-gray-500 no-underline hover:text-neutral-900"
            to="/blogs"
          >
            ← All posts
          </Link>

          <div className="flex flex-col gap-2.5 mt-4 mb-5">
            <span className="bg-black text-white w-max rounded px-2 py-1 text-sm font-light">
              {post.category}
            </span>
            <h1 className="text-3xl md:text-4xl font-semibold leading-tight">
              {post.title}
            </h1>
            <p className="text-gray-500 text-sm">
              {formatDate(post.date)} · {post.minutes} min read
            </p>
          </div>

          <img
            src={post.image}
            alt={post.title}
            className="w-full rounded-xl shadow-soft"
          />

          <p className="text-lg text-gray-600 my-5">{post.excerpt}</p>

          {toc.length > 1 && (
            <div className="sticky top-16 z-30 bg-white py-4">
              <select
                className="w-full p-2.5 text-base font-medium border border-gray-300 rounded outline-none"
                onChange={(e) => e.target.value && jumpTo(e.target.value)}
                defaultValue=""
                aria-label="Jump to section"
              >
                <option value="">Table of Contents</option>
                {toc.map((t) => (
                  <option key={t.id} value={t.id}>
                    {t.level === 3 ? "— " : ""}
                    {t.text}
                  </option>
                ))}
              </select>
            </div>
          )}

          <article
            className="prose prose-lg max-w-none prose-headings:scroll-mt-24 prose-headings:font-semibold prose-a:text-brand-ink prose-code:before:content-none prose-code:after:content-none"
            dangerouslySetInnerHTML={{ __html: html }}
          />

          <div className="flex flex-wrap gap-2 my-8">
            {post.tags.map((t) => (
              <Link
                key={t}
                className={tagCls}
                to={`/blogs?tag=${encodeURIComponent(t)}`}
              >
                #{t}
              </Link>
            ))}
          </div>

          <div className="flex justify-between gap-4 border-t border-gray-200 pt-5">
            {prev ? (
              <Link
                className="max-w-[48%] text-gray-500 no-underline font-medium hover:text-neutral-900"
                to={`/blogs/${prev.slug}`}
              >
                ← {prev.title}
              </Link>
            ) : (
              <span />
            )}
            {next ? (
              <Link
                className="max-w-[48%] text-right text-gray-500 no-underline font-medium hover:text-neutral-900"
                to={`/blogs/${next.slug}`}
              >
                {next.title} →
              </Link>
            ) : (
              <span />
            )}
          </div>
        </div>
      </div>
    </Fragment>
  );
};

export default BlogDetail;
