import { useEffect } from "react";
import { useLocation } from "react-router-dom";

// Reset scroll to the top on every route change (SPA default keeps scroll position).
// Skips when navigating to an in-page section (handled by the header's smooth scroll).
const ScrollToTopOnNav = () => {
  const { pathname, hash } = useLocation();

  useEffect(() => {
    if (hash) return; // let anchor/section links control the scroll
    window.scrollTo({ top: 0, left: 0, behavior: "instant" });
  }, [pathname, hash]);

  return null;
};

export default ScrollToTopOnNav;
